import{_ as a,o as t,c as n,a3 as i}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"模型选型、评测、成本与延迟","description":"","frontmatter":{"title":"模型选型、评测、成本与延迟","article":{"type":"decision","structure":"decision"}},"headers":[],"relativePath":"ts-ai/foundations/model/model-selection-evaluation-cost-latency.md","filePath":"ts-ai/foundations/model/model-selection-evaluation-cost-latency.md","lastUpdated":1786083160000}'),e={name:"ts-ai/foundations/model/model-selection-evaluation-cost-latency.md"};function l(p,s,d,r,h,o){return t(),n("div",null,[...s[0]||(s[0]=[i(`<h1 id="模型选型、评测、成本与延迟" tabindex="-1">模型选型、评测、成本与延迟 <a class="header-anchor" href="#模型选型、评测、成本与延迟" aria-label="Permalink to &quot;模型选型、评测、成本与延迟&quot;">​</a></h1><blockquote><p>作者：cursor-grok-4.5</p></blockquote><p>模型选型不是从排行榜挑“最聪明”的名字，而是在真实任务、质量门槛、延迟预算、数据约束和成本之间做可复查决策。正确顺序是先定义任务与失败，再筛硬条件，最后用同一数据集测候选模型。</p><h2 id="_1-决策背景" tabindex="-1">1. 决策背景 <a class="header-anchor" href="#_1-决策背景" aria-label="Permalink to &quot;1. 决策背景&quot;">​</a></h2><p>本文以“退款政策助手”为例。它接收用户问题和已授权政策片段，输出带来源的判断；信息不足时拒答，不直接执行退款。这个边界会直接改变模型要求：</p><ul><li>需要可靠的中文指令遵循和结构化输出；</li><li>需要足够上下文容纳政策，但不需要无限窗口；</li><li>不要求模型原生联网，事实来自应用提供的来源；</li><li>需要低延迟对话，批量离线吞吐不是唯一目标；</li><li>错误批准退款比保守拒答更严重。</li></ul><p>若任务换成代码生成、图片质检或长篇研究，候选和指标都应重新定义，不能复用同一个“最佳模型”结论。</p><h2 id="_2-写出任务契约" tabindex="-1">2. 写出任务契约 <a class="header-anchor" href="#_2-写出任务契约" aria-label="Permalink to &quot;2. 写出任务契约&quot;">​</a></h2><p>选型前为每类任务填写：</p><table tabindex="0"><thead><tr><th>项目</th><th>退款助手示例</th></tr></thead><tbody><tr><td>输入</td><td>用户问题、订单的授权摘要、最多 8 条政策片段</td></tr><tr><td>输出</td><td><code>answered</code> / <code>insufficient_evidence</code>、结论、逐条引用</td></tr><tr><td>严重失败</td><td>无来源批准、引用不存在、泄露其他用户订单、越权调用工具</td></tr><tr><td>可接受失败</td><td>信息不足时转人工，或回答延迟略高</td></tr><tr><td>质量门槛</td><td>严重失败为 0；结构有效率 ≥ 99%；边界题准确率 ≥ 95%</td></tr><tr><td>延迟预算</td><td>服务端模型阶段 p95 ≤ 4 秒</td></tr><tr><td>成本预算</td><td>每个成功解决会话的模型成本 ≤ 业务设定上限</td></tr></tbody></table><p>阈值必须来自产品风险和流量经济性。上表数值只是填写示例，不是所有项目的行业标准。</p><h2 id="_3-用硬条件筛选候选" tabindex="-1">3. 用硬条件筛选候选 <a class="header-anchor" href="#_3-用硬条件筛选候选" aria-label="Permalink to &quot;3. 用硬条件筛选候选&quot;">​</a></h2><p>不满足硬条件的模型不进入综合评分：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>供应区域与数据政策</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>输入 / 输出模态</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>上下文窗口与最大输出</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>结构化输出与工具能力</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>吞吐、配额和可用性</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>候选集合</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><p>检查项包括：</p><ul><li>数据是否允许发送到该供应商、区域和日志策略；</li><li>模型是否支持所需语言、图片、工具或严格 Schema；</li><li>上下文窗口是否能容纳真实 p95 输入加输出预留；</li><li>账号是否有稳定配额、并发和目标区域可用性；</li><li>SDK、网关与 LangChain.js 集成是否保留所需元数据；</li><li>模型名是固定版本、滚动别名还是预览版，升级策略是什么。</li></ul><p>模型 Profile 和文档适合初筛，最终仍以目标账号、区域和实际调用验证。</p><p>LangChain.js v1 可以读取集成本地维护的能力提示，适合把明显不满足条件的候选提前排除：</p><div class="language-ts vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> profile</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> model.profile</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> snapshot</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  maxInputTokens: profile.maxInputTokens,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  maxOutputTokens: profile.maxOutputTokens,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  imageInputs: profile.imageInputs,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  toolCalling: profile.toolCalling,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  structuredOutput: profile.structuredOutput,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p>不要把缺失字段自动解释为“不支持”，也不要把 <code>true</code> 解释为当前账号必然可用。把 Profile 快照、供应商文档、账号实测和集成测试结果一起写进候选记录，才能区分“模型能力不足”和“本地资料尚未覆盖”。</p><h2 id="_4-建立代表性评测集" tabindex="-1">4. 建立代表性评测集 <a class="header-anchor" href="#_4-建立代表性评测集" aria-label="Permalink to &quot;4. 建立代表性评测集&quot;">​</a></h2><p>评测集应来自真实任务分布，并刻意增加高风险样例：</p><table tabindex="0"><thead><tr><th>分层</th><th>样例</th><th>目的</th></tr></thead><tbody><tr><td>常规</td><td>明确符合 7 天规则</td><td>测主流程</td></tr><tr><td>边界</td><td>刚好第 7 天、时区跨日</td><td>测规则边界</td></tr><tr><td>信息不足</td><td>没有签收时间</td><td>测拒答与追问</td></tr><tr><td>冲突证据</td><td>新旧政策同时召回</td><td>测版本与来源处理</td></tr><tr><td>对抗</td><td>文档中要求忽略系统规则</td><td>测 Prompt Injection</td></tr><tr><td>长上下文</td><td>多条相似但无关政策</td><td>测检索噪声和位置效应</td></tr><tr><td>格式压力</td><td>特殊字符、空文本、超长订单号</td><td>测 Schema 稳定性</td></tr></tbody></table><p>每条样例至少包含输入、允许使用的来源、期望结论、不可接受行为和评分标签：</p><div class="language-json vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;refund-boundary-007&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;question&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;签收满 7 个自然日的当天还能申请吗？&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;sourceIds&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;refund-policy-v3#section-2&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;expectedStatus&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;answered&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;expectedDecision&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;eligible&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;forbidden&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;引用不存在的来源&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;直接调用退款工具&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;tags&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;boundary&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;date&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p>开发集用于调 Prompt，测试集应冻结并避免反复人工针对单题优化。线上失败样例经脱敏和审核后持续回流为新版本数据集。</p><h2 id="_5-分开度量质量" tabindex="-1">5. 分开度量质量 <a class="header-anchor" href="#_5-分开度量质量" aria-label="Permalink to &quot;5. 分开度量质量&quot;">​</a></h2><p>不要只生成一个模糊“综合得分”。至少分别记录：</p><table tabindex="0"><thead><tr><th>指标</th><th>计算</th><th>为什么独立保留</th></tr></thead><tbody><tr><td>Schema 有效率</td><td>合法结构数 / 总调用数</td><td>结构失败会直接阻塞系统</td></tr><tr><td>任务准确率</td><td>正确结论数 / 可回答样例数</td><td>衡量主要任务能力</td></tr><tr><td>正确拒答率</td><td>信息不足时正确拒答数 / 不可回答样例数</td><td>防止模型强行作答</td></tr><tr><td>引用有效率</td><td>存在且可定位的引用数 / 全部引用数</td><td>防止虚构来源</td></tr><tr><td>严重失败数</td><td>越权、泄密、错误执行等次数</td><td>高风险任务应设为硬门禁</td></tr><tr><td>格式外修复率</td><td>需要额外解析或重试的比例</td><td>反映隐藏延迟与成本</td></tr></tbody></table><p>事实支持程度通常不能只靠字符串匹配。可以先做确定性检查（来源 ID 存在、引文确实出现），再对“来源是否支持主张”进行人工评审或独立 Evaluator；LLM Judge 自身也要用标注集校准。</p><p>每个候选至少多次运行容易波动的样例，并报告置信区间或原始分布。单次运行的漂亮答案不是模型稳定性证据。</p><h2 id="_6-延迟应拆成分布" tabindex="-1">6. 延迟应拆成分布 <a class="header-anchor" href="#_6-延迟应拆成分布" aria-label="Permalink to &quot;6. 延迟应拆成分布&quot;">​</a></h2><p>一次用户可见延迟包括：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>排队 + Prompt 组装 + 首 Token 等待 + 流式生成</span></span>
<span class="line"><span>+ 工具 / 检索 + 重试退避 + 输出校验 + 网络传输</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>至少记录：</p><ul><li>首 Token 时间，决定用户何时看到反馈；</li><li>完整响应时间，决定任务何时可提交；</li><li>p50、p95、p99，而不只平均值；</li><li>输入和输出 Token，帮助解释延迟差异；</li><li>限流、超时和重试次数；</li><li>按区域、模型和任务类型分组的数据。</li></ul><p>测试应使用接近生产的并发和输入长度。串行调用十个短 Prompt 得到的平均延迟，无法代表晚高峰长上下文请求。</p><h2 id="_7-计算每个成功任务的成本" tabindex="-1">7. 计算每个成功任务的成本 <a class="header-anchor" href="#_7-计算每个成功任务的成本" aria-label="Permalink to &quot;7. 计算每个成功任务的成本&quot;">​</a></h2><p>单次模型价格只是成本的一部分：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>单次调用成本</span></span>
<span class="line"><span>= 输入 Token 成本</span></span>
<span class="line"><span>+ 输出 Token 成本</span></span>
<span class="line"><span>+ 缓存、搜索、图片或工具附加费用</span></span>
<span class="line"><span></span></span>
<span class="line"><span>每个成功任务成本</span></span>
<span class="line"><span>= 所有调用与重试成本</span></span>
<span class="line"><span>+ Agent 循环和评测成本</span></span>
<span class="line"><span>+ 失败后转人工或再次处理成本</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p>例如模型 B 单次价格低，但结构失败导致 15% 重试，模型 A 价格略高却一次完成。应比较：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cost_per_success = 总模型与附加费用 / 成功完成的任务数</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>还要计算月度上界：峰值流量 × 每任务调用数 × p95 Token × 单价，并加入限流和预算报警。价格、缓存折扣和免费额度会变化，应放在可更新配置而不是写死在业务代码。</p><h2 id="_8-做出可复查决策" tabindex="-1">8. 做出可复查决策 <a class="header-anchor" href="#_8-做出可复查决策" aria-label="Permalink to &quot;8. 做出可复查决策&quot;">​</a></h2><p>下面是评测后的示例记录，数字仅演示决策方法：</p><table tabindex="0"><thead><tr><th>指标</th><th style="text-align:right;">候选 A</th><th style="text-align:right;">候选 B</th><th style="text-align:right;">门槛</th></tr></thead><tbody><tr><td>Schema 有效率</td><td style="text-align:right;">99.6%</td><td style="text-align:right;">98.7%</td><td style="text-align:right;">≥ 99%</td></tr><tr><td>边界题准确率</td><td style="text-align:right;">96.2%</td><td style="text-align:right;">96.8%</td><td style="text-align:right;">≥ 95%</td></tr><tr><td>正确拒答率</td><td style="text-align:right;">97.1%</td><td style="text-align:right;">91.4%</td><td style="text-align:right;">≥ 95%</td></tr><tr><td>严重失败</td><td style="text-align:right;">0</td><td style="text-align:right;">0</td><td style="text-align:right;">0</td></tr><tr><td>完整延迟 p95</td><td style="text-align:right;">3.6 s</td><td style="text-align:right;">2.4 s</td><td style="text-align:right;">≤ 4 s</td></tr><tr><td>每成功任务成本</td><td style="text-align:right;">0.8 个预算单位</td><td style="text-align:right;">0.5 个预算单位</td><td style="text-align:right;">≤ 1</td></tr></tbody></table><p>候选 B 虽然更快、更便宜，但没有达到 Schema 和拒答门槛，因此不能作为当前主模型。合理决策可以是：</p><ul><li>候选 A 作为退款判断主模型；</li><li>候选 B 只用于低风险摘要，使用独立 Schema 和评测门槛；</li><li>若 A 超时，返回“暂时无法判断”或转人工，而不是无条件用 B 产生退款结论。</li></ul><p>这不是永久结论。记录数据集版本、Prompt 版本、模型标识、参数、日期、区域和评测代码，才能在价格或模型升级后复现。</p><h2 id="_9-路由、回退与复查条件" tabindex="-1">9. 路由、回退与复查条件 <a class="header-anchor" href="#_9-路由、回退与复查条件" aria-label="Permalink to &quot;9. 路由、回退与复查条件&quot;">​</a></h2><p>只有单模型无法同时满足不同任务约束时，才增加路由：</p><ul><li>低风险分类使用小模型，高风险决策使用通过更严格门槛的模型；</li><li>长上下文请求路由到支持足够窗口的模型；</li><li>图片请求只进入经过多模态评测的模型；</li><li>回退模型必须满足该任务的最低契约，不能只因“可用”就接管。</li></ul><p>新增路由会增加测试矩阵、缓存分散、追踪复杂度和故障组合。先建立单模型基线，再证明路由带来的质量或成本收益。</p><p>满足以下条件之一时重跑评测并复查决策：模型或别名升级、价格变化、Prompt / Schema 变化、任务分布漂移、严重线上失败、供应商区域或数据政策变化。选型的产物不是模型名，而是一份能用数据重新执行的决策记录。</p>`,54)])])}const k=a(e,[["render",l]]);export{u as __pageData,k as default};
